/* ---------- AIC-11 Agent memory ---------- */
a2Page({path:'/admin/ai/memory', section:'ai', tab:'memory', en:'Agent memory', bn:'এজেন্টের মনে রাখা', perm:'ai.read', syn:'memory agent facts correct forget', render:function(p, q, ctx){
  var ai = a2bAI(), sel = q.a && ai.mem[q.a] ? q.a : (ui('a2b-mem', {a:'gyani'}).a), can = a2Can('ai.control');
  var chips = '<div class="a2-views">' + A2B_AGENTS.map(function(id){ var a = a2bAg(id); return '<a class="a2-view' + (sel === id ? ' on' : '') + '" href="#/admin/ai/memory?a=' + id + '">' + Le(a.en, a.bn) + '<span class="a2-cnt">' + (ai.mem[id] || []).filter(function(x){ return !x.arch; }).length + '</span></a>'; }).join('') + '</div>';
  var items = (ai.mem[sel] || []);
  var body = '<section class="a2-card">' + (items.length ? items.map(function(x){ return '<div class="a2b-dr' + (x.arch ? ' arch' : '') + '"><span class="a2-tki ' + (x.by === 'Rule' ? 'info' : x.by === 'Owner' ? 'warn' : 'mute') + '">' + a2i(x.by === 'Rule' ? 'shield' : x.by === 'Owner' ? 'users' : 'spark', 15) + '</span><div><b>' + esc(x.t) + '</b><span class="a2-xs a2-mute">' + esc(x.by) + ' · ' + a2date(x.at) + (x.v ? ' · v' + x.v : '') + (x.arch ? ' · ' + L('archived', 'আর্কাইভ') : '') + '</span></div>' + (can ? '<div class="a2-gap8"><button type="button" class="a2-btn sm" data-act="a2b-memed" data-a="' + sel + '" data-id="' + x.id + '">' + a2i('edit', 14) + Le('Correct', 'ঠিক করুন') + '</button><button type="button" class="a2-btn sm ghost" data-act="a2b-memarch" data-a="' + sel + '" data-id="' + x.id + '">' + (x.arch ? Le('Restore', 'ফেরান') : Le('Archive', 'আর্কাইভ')) + '</button></div>' : '') + '</div>'; }).join('') : '<div class="a2-sm a2-mute">' + Le('Nothing remembered yet', 'এখনো কিছু মনে রাখেনি') + '</div>') + '</section>';
  return a2Head(ctx, {sub:Le('What each agent remembers. Correct a wrong memory; archive one it should stop using. Every change is versioned.', 'প্রতিটা এজেন্ট কী মনে রাখে। ভুল ঠিক করুন; দরকার না হলে আর্কাইভ।') + ' ' + a2bMark('plan'), right:can ? '<button type="button" class="a2-btn pri" data-act="a2b-memadd" data-a="' + sel + '">' + a2i('plus', 15) + Le('Add a memory', 'নতুন যোগ') + '</button>' : ''}) + a2Tabs(ctx) + chips + body;
}});
function a2bMemItem(el){ return (a2bAI().mem[el.getAttribute('data-a')] || []).filter(function(x){ return x.id === el.getAttribute('data-id'); })[0]; }
ACT['a2b-memed'] = function(el){ var x = a2bMemItem(el); if(!x) return; a2Confirm({title:'Correct this memory', bn:'মনে রাখা ঠিক করুন', body:'<label class="a2-lbl" for="a2b-mt">' + Le('Memory', 'মনে রাখা') + '</label><textarea id="a2b-mt" class="a2-ta" rows="3" data-f="t">' + esc(x.t) + '</textarea>', effects:[L('The old wording is kept as an earlier version', 'আগের লেখা পুরনো ভার্সন হিসেবে থাকবে')], ok:'Save', okBn:'সেভ', fn:function(r, v){ if(!v.t || v.t === x.t) return; x.prev = (x.prev || []).concat([x.t]); x.t = v.t; x.v = (x.v || 1) + 1; x.by = 'Owner'; x.at = Date.now(); a2Log('Corrected memory of ' + el.getAttribute('data-a')); saveState(); rerender(); toast(L('Saved', 'সেভ হয়েছে')); }}); };
ACT['a2b-memarch'] = function(el){ var x = a2bMemItem(el); if(!x) return; x.arch = !x.arch; a2Log((x.arch ? 'Archived' : 'Restored') + ' a memory of ' + el.getAttribute('data-a')); saveState(); rerender(); toast(x.arch ? L('Archived — the agent stops using it', 'আর্কাইভ — এজেন্ট আর ব্যবহার করবে না') : L('Restored', 'ফেরানো হয়েছে')); };
ACT['a2b-memadd'] = function(el){ var a = el.getAttribute('data-a'); a2Confirm({title:'Add a memory', bn:'নতুন মনে রাখা', body:'<label class="a2-lbl" for="a2b-mn">' + Le('What should the agent remember?', 'এজেন্ট কী মনে রাখবে?') + '</label><textarea id="a2b-mn" class="a2-ta" rows="3" data-f="t"></textarea>', ok:'Add', okBn:'যোগ', fn:function(r, v){ if(!v.t) return; (a2bAI().mem[a] = a2bAI().mem[a] || []).unshift({id:'m' + Date.now(), t:v.t, by:'Owner', at:Date.now(), v:1}); a2Log('Added memory to ' + a); saveState(); rerender(); toast(L('Added', 'যোগ হয়েছে')); }}); };

